INSERT INTO `coding_class_info` (`coding_id`, `title`, `content`, `type`, `organization`, `level`, `start_date`, `end_date`, `duration`, `contact_info`, `coding_image`, `created_at`) VALUES
(11, 'PHP Boot Camp', 'သင်တန်းကြေး - 150000 MMK\r\nIT သမားတယောက်အနေနဲ့ Web development ကိုအခြေခံကနေစနစ်တကျသင်ယူချင်တယ်ဆိုရင် O-Technique Myanmar ရဲ့ Boot Camp သင်တန်းကိုတက်သင့်ပါတယ်။\r\n\r\nသင်ကြားပေးသွားမည့် Course Design နှင့် benefits တွေကတော့\r\n ✅Module 1 : HTML , CSS, JS, Bootstrap \r\n      Project : My Portfolio, Admin Panel\r\n ✅Module 2 : Php , MySql, Laravel ,\r\n       Project: Ecommerce Site with Credit Payment\r\nဘဲဖြစ်ပါတယ်။', 'PHP', 'O-Technique Myanmar', 'beginner', '2025-10-01', '2026-02-21', '4 months 23 days', '09 42073 4603 ,09 4315 9715', , '2025-09-10 15:57:26');
INSERT INTO `coding_class_info` (`coding_id`, `title`, `content`, `type`, `organization`, `level`, `start_date`, `end_date`, `duration`, `contact_info`, `coding_image`, `created_at`) VALUES
(12, 'Data Analyst All-in-One Course ', 'သင်တန်းကြေး - 300000 MMK\r\nဒီသင်တန်းကိုဘယ်သူတွေတက်ရောက်သင့်လဲဆိုရင်\r\n- လုပ်ငန်းကြီးတွေမှာ Data Analyst, Business Analyst အဖြစ် ဝင်ရောက်ချင်သူ\r\n- အထူးကောင်းမွန်တဲ့ ဝင်ငွေလမ်းကြောင်းကို ရချင်သူ\r\n- ကိုယ့်ရဲ့ Career ကို တစ်ဆင့်မြှင့်တင်ချင်သူ\r\n- ဘယ်တော့မှ တိမ်ကောမသွားမယ့် Career တစ်ခုကို ရှာဖွေနေသူ\r\n- ပြည်တွင်းပြည်ပဘယ်နေရာရောက်ရောက် အလုပ်ခွင်တိုင်းမှာဝင်ဆံ့ချင်သူတစ်ဦးဆိုရင် Success Point ရဲ့  𝐃𝐚𝐭𝐚 𝐀𝐧𝐚𝐥𝐲𝐬𝐭 𝐀𝐥𝐥-𝐢𝐧-𝐨𝐧𝐞 𝐂𝐨𝐮𝐫𝐬𝐞 ကိုရွေးချယ်သင့်ပါတယ်။\r\n\r\nဒီအတန်းမှာ ဆိုရင် -\r\n✅𝐏𝐲𝐭𝐡𝐨𝐧\r\n✅𝐒𝐐𝐋\r\n✅𝐏𝐨𝐰𝐞𝐫 𝐁𝐈\r\n✅𝐒𝐭𝐚𝐭𝐢𝐬𝐭𝐢𝐜𝐬 စတဲ့ ပညာရပ်တွေကို အခြေခံကစပြီး advanced အထိ Projects များနှင့် ကိုယ်တိုင် analysis လုပ်နိုင်တဲ့အထိသင်ကြားပေးသွားမှာဘဲဖြစ်ပါတယ်။\r\n သင်တန်းပြီးတဲ့အခါမှာလဲ assignment & projects တွေတင်ပြီးတာနဲ့ Certificate ရမှာဘဲဖြစ်ပါတယ်။', 'Python', 'Success Point IT & Language School ', 'intermediate', '0000-00-00', '0000-00-00', NULL, '09250534703', , '2025-09-10 16:02:49');
INSERT INTO `coding_class_info` (`coding_id`, `title`, `content`, `type`, `organization`, `level`, `start_date`, `end_date`, `duration`, `contact_info`, `coding_image`, `created_at`) VALUES
(13, 'Fundamental Linux Class', 'သင်တန်းကြေး - 300000 MMK\r\nဒီအတန်းကိုဘယ်သူတွေ တက်ရောက်သင့်သလဲဆိုရင် IT career နှင့် အသက်မွေး၀မ်းကျောင်းပြုလုပ်မယ့် မည်သူမဆိုတက်ရောက်သင့်သော အတန်းဘဲဖြစ်ပါတယ်။ \r\n \r\nCourse Outlines\r\n✅ Module 1 Introduction to Linux \r\n✅ Module 2 Using Virtualization \r\n✅ Module 3 Linux OS Installation \r\n✅ Module 4 Welcome Shell and Kernel \r\n✅ Module 5 Various Desktop Environment\r\n✅ Module 6 Software Installation and Customization \r\n✅ Module 7 Linux Directory Structure \r\n✅ Module 8 File and Directory Permission \r\n✅ Module 9 Essential Command \r\n', 'Linux', 'Success Point IT & Language Schoo', 'intermediate', '2025-06-30', '2025-11-06', '4 months 9 days', '09887788439, 09267777960,09952421359', , '2025-09-10 16:07:26');
INSERT INTO `coding_class_info` (`coding_id`, `title`, `content`, `type`, `organization`, `level`, `start_date`, `end_date`, `duration`, `contact_info`, `coding_image`, `created_at`) VALUES
(14, 'UX/UI Basic Class', 'ဒီသင်တန်းကို ဘယ်သူတွေတတ်ရောက်သင့်လဲဆိုရင်\r\n- Design ကိုစိတ်ဝင်စားသူများ – Graphic Design သာမက Digital Product Design (Web/App) ကိုလေ့လာချင်သူ\r\n- Beginner Level ကနေ UI/UX ကိုစတင်လေ့လာချင်သူများ – Code မရေးတတ်ဘဲ UI/UX Design ကို သုညမှ စတင်လေ့လာလိုသူ\r\n- တက္ကသိုလ်ကျောင်းသား/သူများ – - Final Year Project / Assignment တွေမှာ Wireframe, Prototype တိုလိုအပ်နေသူ\r\n- Freelancer / Startup လုပ်ချင်သူများ – Client များအတွက် Website & Mobile App Design ကို ကိုယ်တိုင်ဖန်တီးချင်သူ\r\n- Web Developer / Frontend Developer များ – UI/UX Principles, User Flow, Usability Testing စတဲ့ Design Thinking Skill တွေထပ်တိုးချင်သူ\r\n- UI/UX Designer ဖြစ်ချင်သူများ – Professional Tools (Figma) အသုံးပြုပြီး Real-World Project တွေနဲ့ လက်တွေ့အတူတကွသင်ယူချင်သူတွေဆိုရင် ဒီသင်တန်းလေးကိုရွေးချယ်သင့်ပါတယ်။\r\n\r\nCourse Outlines\r\n✅ Introduction to UI/UX (principles, user-centered design)\r\n✅ Wireframing and prototyping (using tools like Figma)\r\n✅ Design best practices and accessibility\r\n✅ User testing and feedback integration and more ….', ' UX/UI', ' COMPU TECH ICT COLLAGE & Ultimate Solution', 'beginner', '0025-09-12', '0025-10-12', '1 months 0 days', '09420298325, 09887788439', , '2025-09-10 16:09:25');
INSERT INTO `coding_class_info` (`coding_id`, `title`, `content`, `type`, `organization`, `level`, `start_date`, `end_date`, `duration`, `contact_info`, `coding_image`, `created_at`) VALUES
(15, 'Java Programming class', 'ဒီသင်တန်းဟာဆိုရင် Programming နဲ့ ပတ်သက်ပြီး အခြေခံရှိသည်ဖြစ်စေ မရှိသည်ဖြစ်စေ လေ့လာနိုင်မှာဖြစ်ပြီး Basic တင် သင်ကြားပေးမှာမဟုတ်ဘဲ Exception Handling,Mysql, Java Database, Collections Framework, Serialization, Design Patterns အစရှိတဲ့ 𝗔𝗱𝘃𝗮𝗻𝗰𝗲𝗱 𝗟𝗲𝘃𝗲𝗹 𝗖𝗼𝗻𝗰𝗲𝗽𝘁𝘀 တွေအထိ စာတွေ့၊ လက်တွေ့သာမကဘဲ Projects တွေ Exams တွေနဲ့ပါ စနစ်တကျ သင်ကြားပိုချပေးသွားမယ့်သင်တန်းလေးဖြစ်တာကြောင့် ရွေးချယ်သင့်တဲ့ သက်တန်းလေးဘဲဖြစ်ပါတယ်။\r\n\r\nသင်ကြားသွားပေးမယ့်အကြောင်းအရာတွေကတော့\r\nModule 1\r\nChapter 01  - The Basics\r\nChapter 02  - Control Statements\r\nChapter 03  - Arrays\r\nFirst Project\r\n\r\nModule 2\r\nChapter 04 - Object & Class\r\nChapter 05 - Inheritance\r\nChapter 06 - Polymorphism\r\nChapter 07 - *\r\nChapter 08 - *\r\nChapter 09 - *\r\nChapter 10 - *\r\nChapter 11 - *\r\nChapter 12 - *  \r\nSecond Project\r\n\r\nModule 3\r\nChapter 13 - Inner Class\r\nChapter 14 - Lambda Function\r\nChapter 15 - List\r\nChapter 16 - *\r\nChapter 17 - *\r\nChapter 18 - *\r\nChapter 19 - *\r\nChapter 20 - *\r\nChapter 21 - *\r\nChapter 22 - *\r\nFinal Project\r\nတိုဘဲဖြစ်ပါတယ်။', 'Java', 'Code Wall Technologies', 'intermediate', '2026-06-08', '2026-09-08', '3 months 2 days', 'codewalltechnologies@gmai.com', , '2025-09-10 16:10:53');
INSERT INTO `coding_class_info` (`coding_id`, `title`, `content`, `type`, `organization`, `level`, `start_date`, `end_date`, `duration`, `contact_info`, `coding_image`, `created_at`) VALUES
(16, ' Fullstack Developer Course ', 'ဒီသင်တန်းဟာဆိုရင် PHP Laravel Language ကို Full Stack roadmap နဲ့အတူ theory တင်မဟုတ်ပဲ project base learning နှင့် လေ့လာလိုသူတွေတက်သက့်တဲ့သင်တန်းလေးဘဲဖြစ်ပါတယ်။ ဒီရဲ့ CODE LAB မှာ မည်သည့် သင်တန်းမဆို တစ်ခါတက်ရုံနဲ့ lifetime video access ကိုလဲ ရရှိမှာဘဲဖြစ်ပါတယ်။\r\n\r\n\r\nဒီအတန်းလေးမှာဆိုရင်\r\n✅ Bootstrap ( Portfolio Project )\r\n✅ JavaScript ( ES6 with API call )\r\n✅ Jquery \r\n✅ PHP \r\n✅ Laravel\r\n✅ POS Project\r\n✅ Database ( MySQL )\r\n✅ API ( with token )\r\n✅ Vue JS ( Basic component) \r\n✅ Domain & Hosting \r\n✅ Server Deployment \r\n\r\nတိုကို အဓိကထားပီး zero level ကနေ တစ်ဆင့်ချင်းစပီးသင်ကြားသွားမှာဖြစ်ပါတယ်။\r\n\r\nသင်တန်းပီးလို သင်ကြားထားတဲ့ project ကိုအပ်နှံနိုင်ရင် Certificate ရရှိမှာဘဲဖြစ်ပါတယ်။', 'Php', 'Code Lab', 'intermediate', '0026-07-12', '2026-11-12', '24004 months 18 days', '09796789321', , '2025-09-10 16:12:34');
INSERT INTO `coding_class_info` (`coding_id`, `title`, `content`, `type`, `organization`, `level`, `start_date`, `end_date`, `duration`, `contact_info`, `coding_image`, `created_at`) VALUES
(21, 'Ethical Hacking and Cyber Security Class', 'ယခုလို နည်းပညာ ခေတ်မှာ မိမိရဲ့ အချက်အလက်တွေ / ရုံးတွေ/ မိမိ လုပ်ငန်းတွေရဲ့  အချက်အလက်တွေကို မပေါက်ကြားအောင် ကာကွယ်ချင်တဲ့သူတဲ့သူတွေအနေနဲ့ Techno learn ရဲ့\"Ethical Hacking & Cyber security class\" ကိုရွေးချယ်တက်ရောက်သင့်ပါတယ်။\r\n\r\nCourse Outline\r\n\r\n✅ IT Career Paths\r\n✅ Networking & Linux for CyberSecurity Specialist\r\n✅ Ethical Hacking & Cybersecurity Theory\r\n✅ Information Gathering, Scanning & Enumeration\r\n✅ Vulnerability Analysis & Buffer Overflow\r\n✅ Malware, Social Engineering & Wi-Fi Hacking\r\n✅ Network Mapper, Nessus & Metasploit\r\n✅ Android, Windows, Linux Exploitation\r\n✅ Post-Exploitation & Privilege Escalation\r\n✅ Infrastructure Attacks (DNS Spoofing, ARP, DHCP)\r\n✅ MITM, Sniffing, Pivoting, Maintaining Access\r\n✅ DoS/DDoS (Theory + Practical)\r\n✅ CVE / CVSS / Vulnerable Box Exploits\r\n✅ CTF Challenges (Theory + Practical)\r\n✅ Virtualization, Cloud Computing\r\n✅ Steganography & Cryptography\r\n✅ Web Security & Bug Bounty Basics\r\n✅ Report Writing, SOC & Blue Team Knowledge\r\n✅ TechnoLearn Exams & Recognized Certification Discussion\r\n\r\nသင်တန်းပြီးဆုံးပါက Certification အတွက် Online Exam ဖြေဆိုရမှာဖြစ်ပြီး  Pass ဖြစ်မှသာ Certificate ထုတ်ပေးမှာဖြစ်ပါတယ်။', 'Java', 'Techno Learn', 'advanced', '2025-12-07', '2025-02-09', '-9 months -1 days', '09766799336', , '2025-09-10 19:10:06');
INSERT INTO `coding_class_info` (`coding_id`, `title`, `content`, `type`, `organization`, `level`, `start_date`, `end_date`, `duration`, `contact_info`, `coding_image`, `created_at`) VALUES
(22, 'Web Development  Foundation class', '“အစကောင်းမှ အနှောင်းသေချာ” ဆိုသလိုပဲ၊ အခုအချိန်မှာ အလုပ်အကိုင် အခွင့်အလမ်းပေါများလာတဲ့အတွက် Website တွေဖန်တီးရတာကို စိတ်ဝင်စားတဲ့လူငယ်တွေအနေနဲ့ အခြေခံကို သေချာနားလည်အောင် သင်ကြားပေးမယ့် သင်တန်းလေးဘဲဖြစ်ပါတယ်။\r\nWeb Development နယ်ပယ်ကို စတင်ခြေလှမ်းချင်သူတွေအတွက် အခက်အခဲဖြစ်စေတဲ့ resource တွေများပြားတာနဲ့ ဘယ်ကနေစရမလဲ ဘာတွေဆက်လေ့လာရမလဲ မသိတာတွေကို ဒီသင်တန်းကနေပြီးမှ ကိုယ်ပိုင်သင်ရိုးနဲ့အတူ လက်တွေ့ project တွေကိုပါ face-to-face သင်ကြားပေးတာမလို နားမလည်မှာက်ုလဲစိတ်ပူစရာမလိုပါဘူး။\r\n\r\nCourse Outline \r\n ✅ HTML\r\n ✅ CSS\r\n ✅ Bootstrap\r\n ✅ Tailwind CSS\r\n ✅ JavaScript\r\n ✅ React.js Basic\r\n\r\nProject ရဲ့ အခြေအနေပေါ်မူတည်ပြီး သင်တန်းအောင်မြင်စွာ ပြီးဆုံးကြောင်း Certificate လည်း ထုတ်ပေးမှာ ဖြစ်ပါတယ်။', ' React.js', ' Creative coder', 'beginner', '2025-09-12', '2025-12-30', '3 months 19 days', '09-957314012', , '2025-09-10 19:11:49');
INSERT INTO `coding_class_info` (`coding_id`, `title`, `content`, `type`, `organization`, `level`, `start_date`, `end_date`, `duration`, `contact_info`, `coding_image`, `created_at`) VALUES
(23, '𝙐𝙄 𝘿𝙚𝙨𝙞𝙜𝙣: 𝘽𝙖𝙨𝙞𝙘 𝙩𝙤 𝘼𝙙𝙫𝙖𝙣𝙘𝙚𝙙 𝘾𝙤𝙪𝙧𝙨𝙚', 'UI/UX နဲ့ ပတ်သက်ပြီး အခြေခံရှိသည်ဖြစ်စေ မရှိသည်ဖြစ်စေ လေ့လာနိုင်မှာဖြစ်ပြီး Basic တင် သင်ကြားပေးမှာမဟုတ်ဘဲ 𝗔𝗱𝘃𝗮𝗻𝗰𝗲𝗱 𝗟𝗲𝘃𝗲𝗹 𝗗𝗲𝘀𝗶𝗴𝗻 𝗦𝘆𝘀𝘁𝗲𝗺𝘀, Project Management, Publishing Design System, Animation Tips တွေနဲ့ Responsive UI Design တွေအထိ Projects တွေ နဲ့  စနစ်တကျ သင်ကြားပိုပေးတဲ့ သင်တန်းကောင်းတခုဖြစ်တဲ့အတွက်ကြောင့်မလို \r\nUX/UI လေ့လာမယ့်သူတွေအတွက် ရွေးချယ် တက်ရောက်သင့်တဲ့သင်တန်းလေးတခုဘဲဖြစ်ပါတယ်။\r\n\r\nသင်ကြားပေးသွားမယ့်အကြောင်းအရာတွေကတော့ -\r\nUI Design and Figma Basic\r\nChapter 01  - Frame & Basics\r\nChapter 02  - Strokes & Shapes\r\nChapter 03  - Text & Text Settings\r\nChapter 04  - *\r\nChapter 05  - *\r\nChapter 06  - *\r\nChapter 07  - *\r\nChapter 08  - *\r\nChapter 09  - *\r\nChapter 10  - *\r\nChapter 11  - *\r\nChapter 12  - *\r\nChapter 13  - Animation\r\nChapter 14  - Decorations\r\n\r\nMobile Design Project\r\nDesign System & Figma Master\r\nChapter 01 - Introduction to Design System\r\nChapter 02 - Color System\r\nChapter 03 - Typography System\r\nChapter 04 - *\r\nChapter 05 - *\r\nChapter 06 - *\r\nChapter 07 - *\r\nChapter 08 - *\r\nChapter 09 - *\r\nChapter 10 - *\r\nChapter 11 - *\r\nChapter 12 - *  \r\nChapter 13 - *\r\nChapter 14 - *\r\nChapter 15 - *\r\nChapter 16 - Migration Styles to Variables\r\nChapter 17 - Advanced Animation\r\nWeb Design Project\r\nတိုဘဲဖြစ်ပါတယ်။', 'UX/UI', 'Code Wall Technologies', 'intermediate', '2025-10-12', '2025-12-20', '2 months 9 days', 'codewall@gmail.com', , '2025-09-10 19:20:51');

--
-- Triggers `coding_class_info`
--
DELIMITER $$
CREATE TRIGGER `set_duration_before_insert` BEFORE INSERT ON `coding_class_info` FOR EACH ROW BEGIN
    SET NEW.duration = CONCAT(
        TIMESTAMPDIFF(MONTH, NEW.start_date, NEW.end_date), ' months ',
        MOD(TIMESTAMPDIFF(DAY, NEW.start_date, NEW.end_date), 30), ' days'
    );
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `set_duration_before_update` BEFORE UPDATE ON `coding_class_info` FOR EACH ROW BEGIN
    SET NEW.duration = CONCAT(
        TIMESTAMPDIFF(MONTH, NEW.start_date, NEW.end_date), ' months ',
        MOD(TIMESTAMPDIFF(DAY, NEW.start_date, NEW.end_date), 30), ' days'
    );
END
$$
DELIMITER ;

