--
-- Triggers `users`
--
DELIMITER $$
CREATE TRIGGER `trg_users_delete` AFTER DELETE ON `users` FOR EACH ROW BEGIN
    INSERT INTO user_audit(user_id, action, changed_by, old_data, new_data)
    VALUES(
        OLD.user_id,
        'DELETE',
        USER(),
        JSON_OBJECT('email', OLD.email, 'status', OLD.status),
        NULL 
    );
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_users_insert` AFTER INSERT ON `users` FOR EACH ROW BEGIN
INSERT INTO user_audit(user_id,action,changed_by,old_data,new_data)
VALUES(
NEW.user_id,
'INSERT',
USER(),
NULL,
JSON_OBJECT('email',NEW.email,'status',NEW.status));
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_users_update` AFTER UPDATE ON `users` FOR EACH ROW BEGIN
    INSERT INTO user_audit(user_id, action, changed_by, old_data, new_data)
    VALUES(
        OLD.user_id,
        'UPDATE',
        USER(),
        JSON_OBJECT('email', OLD.email, 'status', OLD.status),
        JSON_OBJECT('email', NEW.email, 'status', NEW.status)
    );
END
$$
DELIMITER ;

-- --------------------------------------------------------

--
-- Table structure for table `user_audit`
--

CREATE TABLE `user_audit` (
  `audit_id` int(11) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `action` enum('INSERT','UPDATE','DELETE') DEFAULT NULL,
  `changed_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `changed_by` varchar(100) DEFAULT NULL,
  `old_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`old_data`)),
  `new_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`new_data`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

